function M.createGallery()
-- Native catalog view. Preview entries describe pictures; the engine owns reward eligibility.
local G={}
local kinds={"outfit","pet","pokemon"}
local tab, page, active=1,1,false
local positions={}
local layoutPositions
local compactGrid
local engine, extras, session, atlas
local bundled, cacheDir
local rows, levels
local families, memberFamily = {}, {}
local sizes
local query, detail, results = "", nil, {}
local editorFile, editorRunning, focusPending, editorSequence
local editorInstance=tostring({}):gsub("[^%w]","")..os.time()
local panelX, panelY = 0, 0

local function dex(number)
    return string.format("#%04d",number)
end

local function sizeSuffix(id)
    local tier=sizes.tiers[sizes.species[id]]
    return tier and (" · "..tier.label) or ""
end

local function matches(item,needle)
    if needle=="" then return true end
    local number=needle:match("^#?(%d+)$")
    local function hit(id,name,no)
        if number then return tonumber(number)==no end
        return id:lower():find(needle,1,true) or name:lower():find(needle,1,true)
    end
    local family=families[memberFamily[item.id]]
    if not family then return hit(item.id,item.name or item.id,item.dex) end
    for _,member in ipairs(family) do
        if hit(member[2],member[3],member[1]) then return true end
    end
    return false
end

-- Lua passes strings to Rainmeter in the Windows code page. Character references
-- let the native meters render UTF-8 catalog labels on any system locale.
local function nativeText(value)
    return (value:gsub("[\128-\255][\128-\191]*",function(char)
        local a,b,c=char:byte(1,3)
        local code
        if #char==2 and a<224 then code=(a-192)*64+b-128
        elseif #char==3 and a<240 then code=((a-224)*64+b-128)*64+c-128 end
        return code and string.format("[\\x%04x]",code) or "?"
    end))
end

local function setting(meter, option, value)
    if option=="Text" or option=="ToolTipText" then value=nativeText(value) end
    SKIN:Bang("!SetOption",meter,option,tostring(value))
end

local function visible(name,yes)
    SKIN:Bang(yes and "!ShowMeter" or "!HideMeter",name)
end

local function catalogRows()
    rows={outfit={},pet={},pokemon={}}
    levels={}
    local indexed={}
    for _,item in ipairs(engine.gallery or {}) do
        if rows[item.kind] then
            table.insert(rows[item.kind],item)
            indexed[item.id]=true
        end
    end
    for _,list in ipairs({engine.catalog or {},extras}) do
        for _,item in ipairs(list) do
            if rows[item.kind] then
                levels[item.id]=item.level
                if not indexed[item.id] then
                    table.insert(rows[item.kind],item)
                    indexed[item.id]=true
                end
            end
        end
    end
    local roots={}
    for _,item in ipairs(rows.pokemon) do
        local root=memberFamily[item.id]
        if not root or item.id==root or not indexed[root] then roots[#roots+1]=item end
    end
    local function number(item)
        for _,member in ipairs(families[memberFamily[item.id]] or {}) do
            if member[2]==item.id then return member[1] end
        end
        return tonumber(item.dex) or math.huge
    end
    table.sort(roots,function(a,b)
        local left,right=number(a),number(b)
        if left==right then return a.id<b.id end
        return left<right
    end)
    rows.pokemon=roots
end

local function imagePath()
    return engine.imageFile(cacheDir,"unlock-gallery",engine.atlas,bundled)
end

local function place(x,y)
    for name,pos in pairs(positions) do
        setting(name,"X",x and x+pos[1] or 0)
        setting(name,"Y",y and y+pos[2] or 0)
    end
    compactGrid=nil
end

-- Reserve one row below the Pokémon grid without resizing the host window.
local function layoutGrid(compact)
    if compactGrid==compact then return end
    compactGrid=compact
    local size=compact and 56 or 64
    for n=1,9 do
        local cell="GalleryCell"..n
        local x=panelX+positions[cell][1]
        local y=panelY+positions[cell][2]-(compact and 12*math.floor((n-1)/3) or 0)
        setting(cell,"Y",y)
        local art="GalleryArt"..n
        setting(art,"X",x+(96-size)/2)
        setting(art,"Y",y+(compact and 3 or 5))
        setting(art,"W",size)
        setting(art,"H",size)
        setting("GalleryLock"..n,"Y",y+5)
        setting("GalleryName"..n,"Y",y+(compact and 63 or 73))
    end
end

local function cell(n,item,owned)
    local shape="Rectangle 0,0,96,"..(compactGrid and 86 or 96)..",2 | StrokeWidth 1 | "
    local colors=owned and "Fill Color 232,241,220 | Stroke Color 148,166,154"
                         or "Fill Color 229,228,218 | Stroke Color 172,175,163"
    local art,lock,name="GalleryArt"..n,"GalleryLock"..n,"GalleryName"..n
    setting("GalleryCell"..n,"Shape",shape..colors)
    visible("GalleryCell"..n,not detail and (item~=nil or tab~=3))
    local click=(tab==3 and item) and ('[!CommandMeasure AvatarUnlocks "GallerySelect('..n..')"]') or ""
    for _,meter in ipairs({"GalleryCell"..n,art,lock,name}) do
        setting(meter,"LeftMouseUpAction",click)
    end
    visible(art,item~=nil)
    visible(lock,item~=nil and not owned)
    visible(name,item~=nil)
    if not item then setting("GalleryCell"..n,"ToolTipText","");return end
    local crop="64,192,12,12"
    if type(item.icon)=="number" and item.icon>=0 then
        crop=string.format("%d,%d,64,64",item.icon%9*64,math.floor(item.icon/9)*64)
    end
    local label=item.name or item.id
    if tab==3 then
        for _,member in ipairs(families[memberFamily[item.id]] or {}) do
            if member[2]==item.id then label=dex(member[1]).." "..label;break end
        end
    end
    local hint=owned and "해금 완료" or (levels[item.id] and "필요 레벨 "..levels[item.id] or "해금 레벨 미정")
    if tab==3 then hint=hint..sizeSuffix(item.id) end
    setting(art,"ImageName",atlas)
    setting(art,"ImageCrop",crop)
    setting(art,"Greyscale",owned and 0 or 1)
    setting(art,"ImageAlpha",owned and 255 or 198)
    setting(name,"Text",label)
    for _,meter in ipairs({"GalleryCell"..n,art,lock,name}) do
        setting(meter,"ToolTipText",label.." · "..hint)
    end
end

function G.refresh()
    if not active then return end
    local entries={}
    for _,item in ipairs(rows[kinds[tab]]) do
        if tab~=3 or matches(item,query:lower()) then entries[#entries+1]=item end
    end
    results=entries
    local family=detail and (families[memberFamily[detail.id]] or {}) or {}
    local parents={}
    for _,member in ipairs(family) do parents[member[1]]=member[3] end
    local pages=math.max(1,math.ceil(#entries/9))
    page=math.max(1,math.min(page,pages))
    local owned,count={},0
    for _,item in ipairs(entries) do
        if session and session:owns(item.id) then owned[item.id]=true;count=count+1 end
    end
    local showSearch=tab==3 and not detail
    layoutGrid(showSearch)
    for i=1,3 do setting("GalleryTabBg"..i,"SolidColor",i==tab and "185,224,190" or "224,226,211") end
    for n=1,9 do
        local item=entries[(page-1)*9+n]
        cell(n,not detail and item or nil,item and owned[item.id])
        local member=family[n]
        visible("GalleryEvolution"..n,member~=nil)
        if member then
            local from=member[4] and ("    "..parents[member[4]].." → ") or ""
            setting("GalleryEvolution"..n,"Text",from..dex(member[1]).." "..member[3]..sizeSuffix(member[2]))
        end
    end
    visible("GallerySearchFrame",showSearch)
    visible("GallerySearch",showSearch)
    visible("GalleryClear",showSearch and query~="")
    visible("GalleryBack",detail~=nil)
    visible("GalleryEmpty",tab==3 and ((not detail and #entries==0) or (detail and #family==0)))
    setting("GalleryEmpty","Text",detail and "등록된 진화 정보가 없어요" or "검색 결과가 없어요")
    local caption=query=="" and "포켓몬 이름 또는 도감 번호" or query
    -- The query is display text, never a Rainmeter variable or action.
    caption=caption:gsub("[#%[%]]",function(c) return string.format("[\\x%04x]",c:byte()) end)
    setting("GallerySearch","Text",caption)
    setting("GalleryTitle","Text",detail and (detail.name or detail.id) or "해금 도감")
    setting("GalleryCount","Text",detail and "진화 계열" or "해금 "..count.." / "..#entries)
    local canFollow=detail and engine.walkRows[detail.id] and session and session:owns(detail.id)
    local followLabel=canFollow and (session:selected("pokemon")==detail.id and "돌려보내기" or "꺼내기")
    setting("GalleryPageNumber","Text",followLabel or (page.." / "..pages))
    setting("GalleryPageNumber","LeftMouseUpAction",canFollow and "[!CommandMeasure AvatarUnlocks GalleryCompanion()]" or "")
    setting("GalleryPageNumber","SolidColor",canFollow and "185,224,190,255" or "0,0,0,0")
    visible("GalleryPageNumber",canFollow or (not detail and pages>1))
    visible("GalleryPrev",not detail and page>1)
    visible("GalleryNext",not detail and page<pages)
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
    SKIN:Bang("!Redraw")
end

function G.init(resources,path,pokedex,pokemonSizes,coordinates)
    layoutPositions=coordinates
    bundled,cacheDir=resources.."unlock-gallery.png",path
    families=pokedex
    sizes=pokemonSizes
    for root,family in pairs(families) do
        for _,member in ipairs(family) do memberFamily[member[2]]=root end
    end
end

function G.prepare()
    if next(positions) then return end
    positions=layoutPositions
    place()
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
end

function G.bind(module,localItems,profile)
    if engine~=module or extras~=localItems then
        engine,extras=module,localItems
        catalogRows()
        atlas=nil
    end
    session=profile
    if active then atlas=atlas or imagePath();G.refresh() end
end

local function stopEditing()
    focusPending=false
    if editorFile then
        os.remove(editorFile)
        editorFile=nil
        SKIN:Bang("!DisableMeasure","GallerySearchWatch")
    end
end

function G.open(x,y)
    local opening=not active
    G.prepare()
    panelX,panelY=x,y
    if not active then place(x,y) end
    active=true
    atlas=atlas or imagePath()
    SKIN:Bang("!ShowMeterGroup","UnlockGallery")
    G.refresh()
    if opening and tab==3 then G.edit() end
end

function G.hide()
    if not active then return end
    active=false
    detail=nil
    stopEditing()
    SKIN:Bang("!HideMeterGroup","UnlockGallery")
    place()
    SKIN:Bang("!UpdateMeterGroup","UnlockGallery")
end

function G.tab(index)
    if not active or not kinds[index] then return end
    if tab~=index or detail then stopEditing() end
    tab,page,detail=index,1,nil
    G.refresh()
    if tab==3 then G.edit() end
end

function G.page(delta)
    if active and not detail and (delta==1 or delta==-1) then page=page+delta;G.refresh() end
end

function G.select(slot)
    if not active or tab~=3 or detail then return end
    detail=results[(page-1)*9+slot]
    if detail then stopEditing();G.refresh() end
end

function G.back()
    detail=nil
    G.refresh()
end

function G.toggleCompanion()
    if not active or not detail or not session or not engine.walkRows[detail.id] or not session:owns(detail.id) then return end
    local id=detail.id
    if session:selected("pokemon")==id then id=nil end
    Choose("pokemon",id)
    ClosePanel()
end

function G.search(text)
    if not active or tab~=3 or detail then return end
    local value=text:match("^%s*(.-)%s*$")
    if value==query then return end
    query,page=value,1
    G.refresh()
end

function G.clear()
    stopEditing()
    G.search("")
end

function G.edit()
    if not active or tab~=3 or detail or editorFile then return end
    if editorRunning then focusPending=true;return end
    editorSequence=(editorSequence or 0)+1
    local token=editorInstance.."_"..editorSequence
    local path=os.getenv("TEMP").."\\FormdaySearch-"..token..".txt"
    local file=io.open(path,"wb")
    if not file then return end
    file:close()
    editorFile,editorRunning=path,true
    SKIN:Bang("!SetVariable","GallerySearchToken",token)
    local pos=positions.GallerySearch
    local x=tonumber(SKIN:GetVariable("CURRENTCONFIGX")) or 0
    local y=tonumber(SKIN:GetVariable("CURRENTCONFIGY")) or 0
    SKIN:Bang("!SetVariable","GallerySearchX",x+panelX+pos[1])
    SKIN:Bang("!SetVariable","GallerySearchY",y+panelY+pos[2])
    SKIN:Bang("!SetVariable","GallerySearchWidth",SKIN:GetMeter("GallerySearch"):GetW())
    local hex=query:gsub(".",function(c) return string.format("%02X",c:byte()) end)
    SKIN:Bang("!SetVariable","GallerySearchSeed",hex)
    SKIN:Bang("!UpdateMeasure","GallerySearchEditor")
    SKIN:Bang("!CommandMeasure","GallerySearchEditor","Run")
    SKIN:Bang("!EnableMeasure","GallerySearchWatch")
end

local function applyHex(hex)
    if hex and #hex%2==0 and #hex<=384 then
        G.search((hex:gsub("%x%x",function(b) return string.char(tonumber(b,16)) end)))
    end
end

function G.tick()
    if not editorFile then return end
    local file=io.open(editorFile,"rb")
    if not file then return end
    local record=file:read(393)
    file:close()
    if record then applyHex(record:match("^QUERY:(%x*)|$")) end
end

function G.edited(output)
    local reopen=focusPending
    if editorFile then applyHex(output:match("^%s*QUERY:(%x*)%s*$")) end
    stopEditing()
    editorRunning=false
    if reopen then G.edit() end
end

return G

end
function M.createFollower()
-- The first gallery image and the live-search timer are free while the book is
-- closed. Reuse them so installed skins can gain a follower through the catalog.
local F={}
local meter,clock="GalleryArt1","GallerySearchWatch"
local id,row,box,scale,width,height,atlas,anchorName
local paused,armed=false,false
local lastX,distance,direction,ground=nil,0,1,nil
local crop,px,py
local panelHome,panelShift=nil,0
-- The currently installed Formday hosts place these controls beside the actor.
-- Leave their original hit boxes and alignment intact when the catalog is open.
local panelMeters=[[CompactCard CompactTitle CompactState DotWorkout RowWorkout CountWorkout
DotCalories RowCalories CountCalories DotProtein RowProtein CountProtein DotBody RowBody CountBody
InfoCard InfoTitle InfoClose ProgressValue Remaining Completed RecordState OpenFolder Unload OpenSite
GameMode ConnectSite ConnectFolder CopySyncFolder UpdateButtonBg UpdateButton UpdateNote InfoGear
SettingsCard SettingsTitle SettingsBack SettingsHint SettingsStartupRow SettingsStartupName SettingsStartupValue
SettingsWalkRow SettingsWalkName SettingsWalkValue SettingsBadgeRow SettingsBadgeName SettingsBadgeValue]]

local function placePanel(rightEdge)
    if not panelHome then
        panelHome={}
        if not SKIN:GetMeter("CompactCard") then return end
        for name in panelMeters:gmatch("%S+") do
            local control=SKIN:GetMeter(name)
            if control then panelHome[name]=tonumber(control:GetOption("X")) or control:GetX() end
        end
    end
    if not panelHome.CompactCard then return end
    local shift=math.max(0,rightEdge-panelHome.CompactCard)
    if shift==panelShift then return end
    for name,home in pairs(panelHome) do
        SKIN:Bang("!SetOption",name,"X",tostring(home+shift))
        SKIN:Bang("!UpdateMeter",name)
    end
    panelShift=shift
end

local function set(name,value) SKIN:Bang("!SetOption",meter,name,tostring(value)) end

local function stop()
    if not armed then return end
    armed=false
    placePanel(0)
    SKIN:Bang("!DisableMeasure",clock)
    SKIN:Bang("!SetOption",clock,"OnUpdateAction","[!CommandMeasure AvatarUnlocks GallerySearchTick()]")
    SKIN:Bang("!HideMeter",meter)
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

local function start()
    if armed or paused or not row or not SKIN:GetMeter(anchorName) then return end
    armed=true
    lastX,distance,crop,px,py,ground=nil,0,nil,nil,nil,nil
    set("ImageName",atlas)
    set("W",width);set("H",height)
    set("Greyscale",0);set("ImageAlpha",255)
    set("ToolTipText","");set("LeftMouseUpAction","")
    SKIN:Bang("!SetOption",clock,"OnUpdateAction","[!CommandMeasure AvatarUnlocks FollowerTick()]")
    SKIN:Bang("!EnableMeasure",clock)
    F.tick()
    SKIN:Bang("!ShowMeter",meter)
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

function F.select(nextId,nextScale,anchor,cacheDir,resources)
    if nextId~=id or nextScale~=scale or anchor~=anchorName then
        stop()
        id,scale,anchorName=nextId,nextScale,anchor
        row=id and M.walkRows[id]
        if row then
            box=M.walkCrops[row+1]
            local pixelScale=scale*box.referenceHeight/box.h
            width=math.max(1,math.floor(box.w*pixelScale+0.5))
            height=math.max(1,math.floor(box.h*pixelScale+0.5))
            if not atlas then atlas=M.imageFile(cacheDir,"unlock-walk",M.walkAtlas,resources.."unlock-walk.png") end
        end
    end
    start()
end

function F.panel(open)
    paused=open
    if open then stop() else start() end
end

function F.tick()
    if not armed then return end
    local actor=SKIN:GetMeter(anchorName)
    if not actor then return end
    local ax,ay,w,h=actor:GetX(),actor:GetY(),actor:GetW(),actor:GetH()
    local x=(tonumber(SKIN:GetVariable("CURRENTCONFIGX")) or 0)+ax
    local dx=lastX and (x-lastX) or 0
    lastX=x
    if dx~=0 then direction=dx>0 and 1 or -1 end
    if dx==0 then distance=0 else distance=(distance+math.abs(dx))%16 end
    local frame=math.floor(distance/4)
    local density=box.density
    local cx=(frame*32+box.x)*density
    local cy=row*64*M.walkDensity+((direction>0 and 32 or 0)+box.y)*density
    local nextCrop=string.format("%d,%d,%d,%d",cx,cy,box.w*density,box.h*density)
    local footInset=tonumber(SKIN:GetVariable("UnlockFollowerFootInset"))
        or (SKIN:GetVariable("UnlockAvatar")=="formday-buddy" and 3 or 0)
    if not ground or SKIN:GetVariable("Pose")~="jump" then ground=ay+h-footInset end
    local nextX,nextY=math.max(0,ax+w),math.max(0,ground-height)
    placePanel(nextX+width+8)
    if crop==nextCrop and px==nextX and py==nextY then return end
    if crop~=nextCrop then set("ImageCrop",nextCrop) end
    if px~=nextX then set("X",nextX) end
    if py~=nextY then set("Y",nextY) end
    crop,px,py=nextCrop,nextX,nextY
    SKIN:Bang("!UpdateMeter",meter)
    SKIN:Bang("!Redraw")
end

return F

end

local function key(value)
    return type(value) == "string" and #value <= 48 and value:match("^[a-z0-9][a-z0-9_-]*$") ~= nil
end

local function exists(path)
    local f = io.open(path,"rb")
    if f then f:close(); return true end
    return false
end

function M.imageFile(cacheDir,name,hex,bundled)
    local path=cacheDir..name.."-"..M.version..".png"
    if exists(path) then return path end
    local temp=path.."."..tostring({}):gsub("[^a-zA-Z0-9]","")..".tmp"
    local file=io.open(temp,"wb")
    if file then
        local bytes=hex:gsub("%x%x",function(pair) return string.char(tonumber(pair,16)) end)
        local written=file:write(bytes)
        local closed=file:close()
        if written and closed and os.rename(temp,path) then return path end
        os.remove(temp)
        if exists(path) then return path end
    end
    return bundled
end

-- Per-avatar signed rules take precedence over bundled copies from older skins.
function M.catalogFor(avatar,localCatalog)
    local rules=M.avatarRewards[avatar] or {}
    local result,signed={},{}
    for _,item in ipairs(rules) do
        result[#result+1]=item
        signed[item.id]=item.kind
    end
    for _,item in ipairs(localCatalog) do
        if not signed[item.id] then result[#result+1]=item
        else assert(signed[item.id]==item.kind,"reward kind changed") end
    end
    return result
end

function M.connect(dataPath, avatar, profile, catalog)
    assert(key(avatar) and key(profile), "invalid avatar or profile")
    local prefix = dataPath .. "unlock~" .. avatar .. "~" .. profile .. "~"
    local pending = prefix .. tostring({}):gsub("[^a-zA-Z0-9]", "") .. "-" .. os.time() .. ".tmp"
    local index, ordered = {}, {}
    local function register(item)
        assert(key(item.id) and key(item.kind) and type(item.level)=="number" and item.level >= 1
            and item.level==math.floor(item.level) and not index[item.id], "invalid reward catalog")
        index[item.id]=item
        ordered[#ordered+1]=item
    end
    for _,item in ipairs(M.catalog) do register(item) end
    for _,item in ipairs(M.catalogFor(avatar,catalog)) do register(item) end
    table.sort(ordered,function(a,b) if a.level==b.level then return a.id<b.id end return a.level<b.level end)
    local session = {}
    function session:owns(id)
        return index[id] ~= nil and exists(prefix .. id .. ".owned")
    end
    function session:sync(level)
        assert(type(level)=="number" and level>=1 and level==math.floor(level),"invalid level")
        local added = {}
        for _,item in ipairs(ordered) do
            if item.level>level then break end
            local path = prefix .. item.id .. ".owned"
            if not exists(path) then
                local file = assert(io.open(pending,"wb"))
                local written = file:write(item.id,"\n")
                local closed = file:close()
                assert(written and closed,"reward save failed")
                -- On Windows rename creates the receipt only if no other instance won.
                if os.rename(pending,path) then added[#added+1]=item.id
                else os.remove(pending); assert(exists(path),"reward commit failed") end
            end
        end
        return added
    end
    function session:selected(kind)
        assert(key(kind),"invalid reward kind")
        local file=io.open(prefix..kind..".selection","rb")
        if not file then return nil end
        local last
        for line in file:lines() do
            local id=line:match("^=([a-z0-9_-]*)!$")
            if id then last=id end
        end
        file:close()
        if index[last] and index[last].kind==kind and self:owns(last) then return last end
    end
    function session:select(kind,id)
        assert(key(kind) and (id==nil or (index[id] and index[id].kind==kind and self:owns(id))),"reward unavailable")
        if self:selected(kind)==id then return end
        local file=assert(io.open(prefix..kind..".selection","ab"))
        local written=file:write("\n="..(id or "").."!\n")
        local closed=file:close()
        assert(written and closed,"selection save failed")
    end
    return session
end
-- Older kits already load verified engines as Lua modules. Switch only the gallery
-- measure to the signed shared file. The host's skin and update service stay independent.
if SKIN and SELF then
    if SKIN:GetMeter("GallerySearchFrame") and SELF:GetName()=="AvatarUnlocks" then
        local dir=os.getenv("LOCALAPPDATA").."\\FormdayAvatar\\Unlocks\\v1\\"
        local pointer=io.open(dir.."active.txt","rb")
        if pointer then
            local active=pointer:read(32);pointer:close()
            if active==M.version then
                SKIN:Bang("!SetOption",SELF:GetName(),"ScriptFile",dir..active..".lua")
            end
        end
    end
    return M
end

-- Rainmeter binding for the independently versioned avatar-unlocks/v1 channel.
local engine = M
local resources, shared, catalog, session, lastLevel
local content, effectiveCatalog
local nextPoll, running, panelOpen, updateCode = 0, false, false, 1
local currentProfile, currentAvatar
local panelPositioned=false
local gallery,showingUpdates,follower
local sizes

local function var(name, value) SKIN:Bang("!SetVariable",name,tostring(value)) end
local function option(name, fallback)
    local value=SKIN:GetVariable(name)
    if value==nil or value=="" then return fallback end
    return value
end
local function validVersion(v) return v and #v<=14 and v:match("^%d+%.%d+%.%d+$") end
local function newer(a,b)
    local ar,as,at=a:match("^(%d+)%.(%d+)%.(%d+)$")
    local br,bs,bt=b:match("^(%d+)%.(%d+)%.(%d+)$")
    if tonumber(ar)~=tonumber(br) then return tonumber(ar)>tonumber(br) end
    if tonumber(as)~=tonumber(bs) then return tonumber(as)>tonumber(bs) end
    return tonumber(at)>tonumber(bt)
end

local function display(code)
    updateCode=code
    var("UnlockUpdateCode",code)
    SKIN:Bang(code==2 and not panelOpen and "!ShowMeterGroup" or "!HideMeterGroup","UnlockUpdateBubble")
    SKIN:Bang(panelOpen and showingUpdates and code==2 and "!ShowMeterGroup" or "!HideMeterGroup","UnlockInstall")
    SKIN:Bang(panelOpen and showingUpdates and code==3 and "!ShowMeterGroup" or "!HideMeterGroup","UnlockRetry")
    SKIN:Bang("!UpdateMeterGroup","UnlockPanel")
    SKIN:Bang("!Redraw")
end

local function loadShared()
    local f=io.open(shared.."active.txt","rb")
    if not f then return end
    local version=f:read(32); f:close()
    if not validVersion(version) or not newer(version,engine.version) then return end
    local path=shared..version..".lua"
    local file=io.open(path,"rb")
    if not file then return end
    local header=file:read("*l");file:close()
    if header=="-- avatar-unlocks/v1 "..version then
        SKIN:Bang("!SetOption",SELF:GetName(),"ScriptFile",path)
    end
end

local function run(mode)
    running=true
    var("UnlockOperation",mode)
    display(mode=="Install" and 4 or 1)
    SKIN:Bang("!UpdateMeasure","AvatarUnlockDownload")
    SKIN:Bang("!CommandMeasure","AvatarUnlockDownload","Run")
end
function Install()
    if panelOpen and showingUpdates and not running and updateCode==2 then run("Install") end
end
function Check()
    if not running then nextPoll=os.time()+300;run("Check") end
end
function OpenPanel()
    if not panelOpen then
        panelOpen=true
        follower.panel(true)
        var("UnlockPanelOpen",1)
        local callback=option("UnlockOnOpen","")
        if callback~="" then SKIN:Bang(callback) end
    end
    showingUpdates=false
    SKIN:Bang("!HideMeterGroup","UnlockPanel")
    gallery.open(tonumber(option("UnlockPanelX",0)) or 0,tonumber(option("UnlockPanelY",0)) or 0)
    display(updateCode)
end
function GalleryTab(index) gallery.tab(index) end
function GalleryPage(delta) gallery.page(delta) end
function GallerySelect(slot) gallery.select(slot) end
function GalleryBack() gallery.back() end
function GallerySearch() gallery.edit() end
function GalleryClear() gallery.clear() end
function GallerySearchTick() gallery.tick() end
function GallerySearchDone() gallery.edited(SKIN:GetMeasure("GallerySearchEditor"):GetStringValue()) end
function OpenUpdates()
    if not panelOpen then OpenPanel() end
    gallery.hide()
    if not panelPositioned then
        local x=tonumber(option("UnlockPanelX",0)) or 0
        local y=tonumber(option("UnlockPanelY",0)) or 0
        for name,pos in pairs(content.panelPositions) do
            SKIN:Bang("!SetOption",name,"X",x+pos[1])
            SKIN:Bang("!SetOption",name,"Y",y+pos[2])
        end
        panelPositioned=true
    end
    showingUpdates=true
    SKIN:Bang("!ShowMeterGroup","UnlockPanel")
    display(updateCode)
    Check()
end
function ClosePanel()
    if not panelOpen then return end
    panelOpen=false
    showingUpdates=false
    gallery.hide()
    var("UnlockPanelOpen",0)
    SKIN:Bang("!HideMeterGroup","UnlockPanel")
    local callback=option("UnlockOnClose","")
    if callback~="" then SKIN:Bang(callback) end
    follower.panel(false)
    display(updateCode)
end
function DownloadFinished()
    local output=SKIN:GetMeasure("AvatarUnlockDownload"):GetStringValue()
    running=false
    local status,version=output:match("^%s*(%u+) (%d+%.%d+%.%d+)%s*$")
    loadShared()
    var("UnlockLatestVersion",version or "-")
    if status=="AVAILABLE" and newer(version,engine.version) then display(2)
    elseif status and version==engine.version then display(0)
    else display(3) end
end

local function readJson(path,decode)
    local file=assert(io.open(path,"rb"))
    local source=file:read("*a")
    file:close()
    return decode(source)
end

local function setCompanion(id)
    local tier=id and sizes.species[id]
    local size=tier and sizes.tiers[tier]
    var("UnlockCompanion",id or "")
    var("UnlockCompanionSize",size and tier or "")
    var("UnlockCompanionScale",size and size.scale or 1)
    follower.select(id,size and size.scale or 1,option("UnlockAvatarMeter","Avatar"),shared,resources)
end

function Initialize()
    resources=SELF:GetOption("ResourcePath")
    local reopen=option("UnlockPanelOpen","0")=="1"
    shared=os.getenv("LOCALAPPDATA").."\\FormdayAvatar\\Unlocks\\v1\\"
    var("UnlockSystemVersion",engine.version)
    var("UnlockLatestVersion",engine.version)
    var("UnlockPanelOpen",0)
    local decode=dofile(resources.."json.lua").decode
    content=decode(engine.contentJson)
    catalog=readJson(option("UnlockCatalog",resources.."unlock-catalog.json"),decode).items
    assert(type(catalog)=="table","missing local reward list")
    sizes=content.sizes
    follower=engine.createFollower()
    setCompanion(nil)
    gallery=engine.createGallery()
    gallery.init(resources,shared,content.families,sizes,content.galleryPositions)
    currentAvatar=option("UnlockAvatar","avatar")
    effectiveCatalog=engine.catalogFor(currentAvatar,catalog)
    gallery.bind(engine,effectiveCatalog,nil)
    display(0)
    if reopen then OpenPanel();OpenUpdates() end
    loadShared()
end

local function updateRewards()
    local avatar=option("UnlockAvatar","avatar")
    local profile=option("UnlockProfile","local")
    if avatar~=currentAvatar or profile~=currentProfile then
        if avatar~=currentAvatar then effectiveCatalog=engine.catalogFor(avatar,catalog) end
        session,lastLevel=nil,nil
        currentAvatar,currentProfile=avatar,profile
        gallery.bind(engine,effectiveCatalog,nil)
        setCompanion(nil)
    end
    local enabled=SKIN:GetVariable("UnlockEnabled")~="0"
    if not enabled or not avatar or not profile or profile=="" then
        if session then gallery.bind(engine,effectiveCatalog,nil) end
        session,lastLevel=nil,nil
        setCompanion(nil);var("UnlockNewItem","")
        return
    end
    local level=tonumber(option("UnlockLevel",SKIN:GetVariable("Level")))
    if not level or level<1 then return end
    if not session then
        session=engine.connect(option("UnlockDataPath",SKIN:GetVariable("CURRENTPATH")),avatar,profile,catalog)
        gallery.bind(engine,effectiveCatalog,session)
        lastLevel=nil
        setCompanion(session:selected("pokemon"))
        var("UnlockNewItem","")
    end
    if level==lastLevel then return end
    local gained=session:sync(level)
    lastLevel=level
    if #gained>0 then gallery.refresh() end
    for _,id in ipairs(gained) do
        var("UnlockNewItem",id)
        local callback=SKIN:GetVariable("UnlockOnGrant") or ""
        if callback~="" then SKIN:Bang(callback) end
    end
end

function GalleryCompanion()
    updateRewards()
    gallery.toggleCompanion()
end

function FollowerTick()
    if option("UnlockEnabled","1")=="0" or currentProfile~=option("UnlockProfile","local") or currentAvatar~=option("UnlockAvatar","avatar") then
        updateRewards()
        return
    end
    follower.tick()
end

function Choose(kind,id)
    updateRewards()
    if session then
        session:select(kind,id)
        if kind=="pokemon" then setCompanion(session:selected("pokemon")) end
    end
end
function Update()
    gallery.prepare()
    if not nextPoll or nextPoll==0 then
        local meter=option("UnlockAvatarMeter","Avatar")
        if SKIN:GetMeter(meter) then
            SKIN:Bang("!SetOption",meter,"LeftMouseDoubleClickAction","[!CommandMeasure AvatarUnlocks OpenPanel()]")
        end
    end
    loadShared()
    updateRewards()
    if not running and os.time()>=nextPoll then Check() end
    return 0
end

return M
